package dev.mobilecodex.app.core;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;
public class SourceBackupHarness {
 static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("assertion "+n);}interface Op{void run()throws Exception;}static void reject(Op o)throws Exception{n++;try{o.run();throw new AssertionError("accepted");}catch(IOException|IllegalArgumentException expected){}}
 static final SourceBackup.Limits L=new SourceBackup.Limits(1000000,2000000,500000,100,200000,32);
 static void zip(Path p,Map<String,byte[]> items)throws Exception{try(var z=new ZipOutputStream(Files.newOutputStream(p))){for(var e:items.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}}
 static Map<String,byte[]> content(Path p)throws Exception{var result=new LinkedHashMap<String,byte[]>();try(var z=new ZipInputStream(Files.newInputStream(p))){ZipEntry e;while((e=z.getNextEntry())!=null)result.put(e.getName(),z.readAllBytes());}return result;}
 public static void main(String[] args)throws Exception{
  if(args.length==3){Path source=Path.of(args[0]),archive=Path.of(args[1]),target=Path.of(args[2]);SourceBackup.write(source,"왕복 앱",archive,SourceBackup.DEFAULT);Files.createDirectory(target);SourceBackup.extract(archive,target,SourceBackup.DEFAULT);System.out.println("Production ZIP roundtrip complete");return;}
  String[] delivered={""};SourceTransfers.failure(null,new IOException("retry"),error->delivered[0]="response",notice->delivered[0]=notice);check(delivered[0].contains("ZIP"));SourceTransfers.failure("id",new IOException("error"),error->delivered[0]=error.getMessage(),notice->delivered[0]="notice");check(delivered[0].equals("error"));
  Path base=Files.createTempDirectory("source-backup-");try{
   Path root=Files.createDirectory(base.resolve("source")),archive=base.resolve("good.zip");Files.createDirectories(root.resolve("app/src/main/java/com/example/build"));Files.writeString(root.resolve("app/src/main/java/com/example/build/한글.java"),"source");Files.writeString(root.resolve("app/build.gradle"),"module");Files.createDirectories(root.resolve("app/build/cache"));Files.writeString(root.resolve("app/build/cache/a.apk"),"omit");Files.createDirectories(root.resolve(".git"));Files.writeString(root.resolve(".git/config"),"private");Files.writeString(root.resolve("local.properties"),"local");Files.createDirectory(root.resolve("empty"));Files.write(root.resolve("wrapper.jar"),new byte[]{0,1,2,3});
   var summary=SourceBackup.write(root,"한글 앱",archive,L);check(summary.name().equals("한글 앱"));check(summary.bytes()>0);check(Files.exists(root.resolve(".git/config")));
   byte[] whole=Files.readAllBytes(archive);Path truncated=base.resolve("truncated.zip");Files.write(truncated,Arrays.copyOf(whole,whole.length-22));reject(()->SourceBackup.inspect(truncated,L));
   var transfers=new SourceTransfers(base.resolve("cache"));
   var preview=transfers.preview(Files.newInputStream(archive),"scope");Path owned=transfers.consume(preview.token(),"scope");check(Files.exists(owned));reject(()->transfers.consume(preview.token(),"scope"));Files.delete(owned);
   var earlier=transfers.preview(Files.newInputStream(archive),"scope");var latest=transfers.preview(Files.newInputStream(archive),"scope");reject(()->transfers.checkedConsume(earlier.token(),"scope",()->{throw new IOException("stale gate");}));Path latestFile=transfers.consume(latest.token(),"scope");check(Files.exists(latestFile));Files.delete(latestFile);
   var queuedOld=transfers.preview(Files.newInputStream(archive),"scope");var queuedNew=transfers.preview(Files.newInputStream(archive),"scope");transfers.cancel(queuedOld.token());Path queuedFile=transfers.consume(queuedNew.token(),"scope");check(Files.exists(queuedFile));Files.delete(queuedFile);
   var unrelated=transfers.preview(Files.newInputStream(archive),"scope");reject(()->transfers.checkedConsume("wrong-token","scope",()->{}));Path unrelatedFile=transfers.consume(unrelated.token(),"scope");check(Files.exists(unrelatedFile));Files.delete(unrelatedFile);
   var allowed=transfers.preview(Files.newInputStream(archive),"scope");boolean[] checked={false};Path applied=transfers.checkedConsume(allowed.token(),"scope",()->checked[0]=true);check(checked[0]);check(Files.exists(applied));reject(()->transfers.consume(allowed.token(),"scope"));Files.delete(applied);
   var denied=transfers.preview(Files.newInputStream(archive),"scope");reject(()->transfers.checkedConsume(denied.token(),"scope",()->{throw new IOException("read-only");}));reject(()->transfers.consume(denied.token(),"scope"));try(var files=Files.list(base.resolve("cache"))){check(files.count()==0);}
   var busy=transfers.preview(Files.newInputStream(archive),"scope");reject(()->transfers.checkedConsume(busy.token(),"scope",()->{throw new IOException("busy");}));reject(()->transfers.consume(busy.token(),"scope"));
   var stale=transfers.preview(Files.newInputStream(archive),"scope");reject(()->transfers.consume(stale.token(),"other"));
   var cancelled=transfers.preview(Files.newInputStream(archive),"scope");transfers.cancel();reject(()->transfers.consume(cancelled.token(),"scope"));
   var data=content(archive);check(!data.containsKey("project/app/build/cache/a.apk"));check(!data.containsKey("project/.git/config"));check(!data.containsKey("project/local.properties"));check(data.containsKey("project/app/src/main/java/com/example/build/한글.java"));
   Path restored=Files.createDirectory(base.resolve("restored"));SourceBackup.extract(archive,restored,L);check(Files.readString(restored.resolve("app/src/main/java/com/example/build/한글.java")).equals("source"));check(Files.isDirectory(restored.resolve("empty")));check(Arrays.equals(Files.readAllBytes(restored.resolve("wrapper.jar")),new byte[]{0,1,2,3}));reject(()->SourceBackup.extract(archive,restored,L));reject(()->SourceBackup.write(root,"name",archive,L));
   int seq=0;for(String bad:List.of("project/../escape","/absolute","project/a\\b","project/a//b","project/./b")){var items=new LinkedHashMap<>(data);items.put(bad,new byte[]{1});Path p=base.resolve("bad"+(seq++)+".zip");zip(p,items);reject(()->SourceBackup.inspect(p,L));}
   var deep=new LinkedHashMap<>(data);String baseManifest=new String(data.get("backup.json"),java.nio.charset.StandardCharsets.UTF_8);String nested=baseManifest.substring(0,baseManifest.length()-1)+",\"extra\":"+"[".repeat(80)+"0"+"]".repeat(80)+"}";deep.put("backup.json",nested.getBytes(java.nio.charset.StandardCharsets.UTF_8));Path deepZip=base.resolve("deep.zip");zip(deepZip,deep);reject(()->SourceBackup.inspect(deepZip,L));
   var version=new LinkedHashMap<>(data);JSONObject manifest=new JSONObject(new String(data.get("backup.json"),java.nio.charset.StandardCharsets.UTF_8));manifest.put("version",2);version.put("backup.json",manifest.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));Path unsupported=base.resolve("version.zip");zip(unsupported,version);reject(()->SourceBackup.inspect(unsupported,L));
   manifest.put("version",1);JSONArray listed=manifest.getJSONArray("entries");listed.put(listed.getJSONObject(0));version.put("backup.json",manifest.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));Path duplicate=base.resolve("duplicate.zip");zip(duplicate,version);reject(()->SourceBackup.inspect(duplicate,L));
   reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1000000,2000000,500000,100,1,32)));reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1000000,2000000,500000,100,200000,1)));
   var changed=new LinkedHashMap<>(data);changed.put("project/wrapper.jar",new byte[]{9});Path bad=base.resolve("hash.zip");zip(bad,changed);reject(()->SourceBackup.inspect(bad,L));
   var missing=new LinkedHashMap<>(data);missing.remove("project/wrapper.jar");Path absent=base.resolve("missing.zip");zip(absent,missing);reject(()->SourceBackup.inspect(absent,L));
   reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1,2000000,500000,100,200000,32)));reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1000000,1,500000,100,200000,32)));reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1000000,2000000,1,100,200000,32)));reject(()->SourceBackup.inspect(archive,new SourceBackup.Limits(1000000,2000000,500000,1,200000,32)));
   Files.createSymbolicLink(root.resolve("linked"),restored);Path fail=base.resolve("link.zip");reject(()->SourceBackup.write(root,"name",fail,L));check(!Files.exists(fail));check(Files.exists(root.resolve("linked"),LinkOption.NOFOLLOW_LINKS));
   Path ordinary=base.resolve("ordinary.zip");zip(ordinary,Map.of("source.txt",new byte[]{1}));reject(()->SourceBackup.inspect(ordinary,L));System.out.println("SourceBackup: "+n+" assertions passed");
  }finally{try(var paths=Files.walk(base)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
 }
}
